/**
 * Deterministic Image Test Fixtures for Section 27-36:
 * - 1x1 transparent PNG
 * - Sample signature PNG
 * - Sample exam candidate photo JPG
 * - Noisy paper signature
 * - Sample WebP/PNG byte buffers
 */

// Valid 1x1 transparent PNG
export const TRANSPARENT_1X1_PNG_BASE64 =
  'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==';

export function getTransparentPngBytes(): Uint8Array {
  return Uint8Array.from(atob(TRANSPARENT_1X1_PNG_BASE64), (c) => c.charCodeAt(0));
}

// 100x100 Red Square PNG
export const RED_SQUARE_PNG_BASE64 =
  'iVBORw0KGgoAAAANSUhEUgAAAGQAAABkCAYAAABw4pVUAAAAP0lEQVR42u3BAQ0AAADCoPdPbQ43oAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAfgw1uAABF9q41gAAAABJRU5ErkJggg==';

export function getRedSquarePngBytes(): Uint8Array {
  return Uint8Array.from(atob(RED_SQUARE_PNG_BASE64), (c) => c.charCodeAt(0));
}

